import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        // core=1, max=2, queue holds 1 task, default policy = Abort
        ThreadPoolExecutor pool = new ThreadPoolExecutor(1, 2, 1, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(1));
        CountDownLatch hold = new CountDownLatch(1); // keeps workers busy
        for (int i = 1; i <= 5; i++) {
            try {
                pool.execute(() -> {
                    try { hold.await(); } catch (InterruptedException e) { }
                });
                System.out.println("task " + i + " accepted: threads=" + pool.getPoolSize()
                        + " queued=" + pool.getQueue().size());
            } catch (RejectedExecutionException e) {
                System.out.println("task " + i + " REJECTED");
            }
        }
        // Rule 1: task1 -> core thread. Rule 2: task2 -> queue.
        // Rule 3: task3 -> extra thread (queue full). Rule 4: tasks 4,5 rejected.
        hold.countDown();
        pool.shutdown();
        pool.awaitTermination(2, TimeUnit.SECONDS);
    }
}

import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        // newFixedThreadPool(2) uses an UNBOUNDED LinkedBlockingQueue
        ThreadPoolExecutor fixed = (ThreadPoolExecutor) Executors.newFixedThreadPool(2);
        CountDownLatch hold = new CountDownLatch(1);
        for (int i = 0; i < 10; i++) {
            fixed.execute(() -> {
                try { hold.await(); } catch (InterruptedException e) { }
            });
        }
        System.out.println("fixed: threads=" + fixed.getPoolSize()
                + " queued=" + fixed.getQueue().size()); // 2 and 8: queue just grows

        // Explicit bounded pool with CallerRuns = back-pressure
        ThreadPoolExecutor safe = new ThreadPoolExecutor(2, 2, 0, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(3), new ThreadPoolExecutor.CallerRunsPolicy());
        System.out.println("safe queue capacity left: " + safe.getQueue().remainingCapacity());
        hold.countDown();
        fixed.shutdown();
        safe.shutdown();
    }
}

import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newSingleThreadExecutor();
        Callable<Integer> ok = () -> 6 * 7;
        Callable<Integer> bad = () -> { throw new IllegalStateException("boom"); };

        Future<Integer> f1 = pool.submit(ok);   // submit wraps it in a FutureTask
        System.out.println("result = " + f1.get());

        Future<Integer> f2 = pool.submit(bad);
        try {
            f2.get();
        } catch (ExecutionException e) {
            // the exception was captured in the FutureTask, not thrown in the worker
            System.out.println("caught: " + e.getCause());
        }

        // FutureTask is both Runnable and Future: we can run it ourselves
        FutureTask<String> ft = new FutureTask<>(() -> "hello from FutureTask");
        new Thread(ft).start();
        System.out.println(ft.get() + ", done=" + ft.isDone());
        pool.shutdown();
    }
}

import java.util.concurrent.*;
import java.util.concurrent.locks.*;

public class Main {
    public static void main(String[] args) throws Exception {
        ReentrantLock lock = new ReentrantLock();
        CountDownLatch held = new CountDownLatch(1);
        CountDownLatch release = new CountDownLatch(1);

        Thread owner = new Thread(() -> {
            lock.lock();
            try {
                held.countDown();
                try { release.await(); } catch (InterruptedException e) { }
            } finally {
                lock.unlock();   // always unlock in finally
            }
        });
        owner.start();
        held.await();

        // synchronized would block forever here; tryLock gives up after 100 ms
        boolean got = lock.tryLock(100, TimeUnit.MILLISECONDS);
        System.out.println("tryLock while busy: " + got);   // false -> fail fast

        release.countDown();
        owner.join();
        System.out.println("tryLock when free: " + lock.tryLock());  // true
        lock.unlock();
    }
}

import java.util.concurrent.locks.*;

public class Main {
    public static void main(String[] args) {
        ReentrantReadWriteLock rw = new ReentrantReadWriteLock();

        // Downgrade: write -> read is allowed
        rw.writeLock().lock();
        rw.readLock().lock();        // take read BEFORE releasing write
        rw.writeLock().unlock();
        System.out.println("downgraded, read holds = " + rw.getReadLockCount());
        rw.readLock().unlock();

        // Upgrade: read -> write is NOT allowed; lock() would deadlock forever
        rw.readLock().lock();
        boolean upgraded = rw.writeLock().tryLock();   // tryLock just reports failure
        System.out.println("upgrade read->write possible? " + upgraded);
        rw.readLock().unlock();

        // Many readers at the same time are fine
        rw.readLock().lock();
        rw.readLock().lock();
        System.out.println("concurrent read holds = " + rw.getReadLockCount());
        rw.readLock().unlock();
        rw.readLock().unlock();
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    public static void main(String[] args) throws Exception {
        // CountDownLatch: wait until 3 services report ready
        CountDownLatch ready = new CountDownLatch(3);
        AtomicInteger started = new AtomicInteger();
        for (int i = 0; i < 3; i++) {
            new Thread(() -> {
                started.incrementAndGet();
                ready.countDown();      // use finally in real code
            }).start();
        }
        ready.await();
        System.out.println("latch released, services started = " + started.get());

        // Semaphore: only 2 concurrent calls to a fragile dependency
        Semaphore permits = new Semaphore(2);
        System.out.println("call 1 allowed: " + permits.tryAcquire());
        System.out.println("call 2 allowed: " + permits.tryAcquire());
        System.out.println("call 3 allowed: " + permits.tryAcquire());  // false
        permits.release();
        System.out.println("after release : " + permits.tryAcquire());

        // CyclicBarrier: 2 parties wait for each other, then barrier action runs
        CyclicBarrier barrier = new CyclicBarrier(2, () -> System.out.println("both arrived"));
        Thread t = new Thread(() -> {
            try { barrier.await(); } catch (Exception e) { }
        });
        t.start();
        barrier.await();
        t.join();
    }
}

import java.util.concurrent.atomic.*;

public class Main {
    // Hand-written CAS retry loop: what incrementAndGet does conceptually
    static int casIncrement(AtomicInteger a) {
        while (true) {
            int old = a.get();
            int next = old + 1;
            if (a.compareAndSet(old, next)) return next;  // lost the race? loop again
        }
    }

    public static void main(String[] args) throws Exception {
        AtomicInteger counter = new AtomicInteger();
        Thread[] ts = new Thread[4];
        for (int i = 0; i < ts.length; i++) {
            ts[i] = new Thread(() -> {
                for (int k = 0; k < 10000; k++) casIncrement(counter);
            });
            ts[i].start();
        }
        for (Thread t : ts) t.join();
        System.out.println("4 threads x 10000 = " + counter.get());

        AtomicInteger x = new AtomicInteger(5);
        System.out.println("CAS(5->9) = " + x.compareAndSet(5, 9) + ", x=" + x.get());
        System.out.println("CAS(5->1) = " + x.compareAndSet(5, 1) + ", x=" + x.get());
        // A single variable only: two fields need a lock or an immutable object
    }
}

import java.util.concurrent.atomic.*;

public class Main {
    public static void main(String[] args) {
        // Plain CAS: value goes A -> B -> A, the stale CAS still succeeds
        AtomicReference<String> top = new AtomicReference<>("A");
        String seen = top.get();            // thread 1 reads A and pauses
        top.set("B");                       // thread 2 changes it...
        top.set("A");                       // ...and changes it back
        System.out.println("plain CAS succeeds (ABA missed): "
                + top.compareAndSet(seen, "X"));

        // Stamped reference: every change bumps the stamp
        AtomicStampedReference<String> s = new AtomicStampedReference<>("A", 0);
        int[] holder = new int[1];
        String seen2 = s.get(holder);       // read value A with stamp 0
        int stamp = holder[0];
        s.set("B", 1);
        s.set("A", 2);                      // value is A again, stamp is 2
        boolean ok = s.compareAndSet(seen2, "X", stamp, stamp + 1);
        System.out.println("stamped CAS succeeds: " + ok);  // false: stale stamp
        System.out.println("value=" + s.getReference() + " stamp=" + s.getStamp());
    }
}

import java.util.*;
import java.util.concurrent.*;

public class Main {
    static final int POISON = -1;

    public static void main(String[] args) throws Exception {
        BlockingQueue<Integer> queue = new ArrayBlockingQueue<>(3); // bounded
        List<Integer> consumed = new ArrayList<>();

        Thread consumer = new Thread(() -> {
            try {
                while (true) {
                    int v = queue.take();        // blocks when empty
                    if (v == POISON) break;      // shutdown signal
                    consumed.add(v * v);
                }
            } catch (InterruptedException e) { }
        });
        consumer.start();

        for (int i = 1; i <= 6; i++) {
            queue.put(i);                        // blocks when full = back-pressure
        }
        System.out.println("offer with timeout when full? " + tryShed());
        queue.put(POISON);                       // one pill per consumer
        consumer.join();
        System.out.println("consumed squares: " + consumed);
    }

    // Load shedding: give up instead of waiting
    static boolean tryShed() throws InterruptedException {
        BlockingQueue<Integer> q = new ArrayBlockingQueue<>(1);
        q.put(1);
        return q.offer(2, 50, TimeUnit.MILLISECONDS);  // false -> reject, return 503
    }
}

import java.util.concurrent.*;

public class Main {
    static CompletableFuture<Integer> fetchUser() {
        return CompletableFuture.supplyAsync(() -> 7);
    }
    static CompletableFuture<String> fetchName(int id) {   // dependent async call
        return CompletableFuture.supplyAsync(() -> "user-" + id);
    }

    public static void main(String[] args) {
        // thenApply = map
        CompletableFuture<Integer> doubled = fetchUser().thenApply(id -> id * 2);
        System.out.println("thenApply   : " + doubled.join());

        // thenApply with an async step would give CompletableFuture<CompletableFuture<..>>
        // thenCompose = flatMap, keeps it flat
        CompletableFuture<String> name = fetchUser().thenCompose(Main::fetchName);
        System.out.println("thenCompose : " + name.join());

        // thenCombine = zip two independent futures
        CompletableFuture<String> both = fetchUser().thenCombine(
                CompletableFuture.supplyAsync(() -> "EU"),
                (id, region) -> id + "@" + region);
        System.out.println("thenCombine : " + both.join());

        // Async variant with our own executor (not the common pool)
        ExecutorService io = Executors.newFixedThreadPool(2);
        String r = fetchUser().thenApplyAsync(id -> "io-" + id, io).join();
        System.out.println("thenApplyAsync: " + r);
        io.shutdown();
    }
}

import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) {
        CompletableFuture<Integer> failing = CompletableFuture.supplyAsync(() -> {
            if (true) throw new IllegalStateException("vendor down");
            return 1;
        });

        // exceptionally: only runs on failure
        System.out.println("exceptionally: " + failing.exceptionally(ex -> -1).join());

        // handle: always runs, sees value and exception
        String h = failing.handle((v, ex) -> ex == null ? "ok " + v
                : "failed: " + ex.getClass().getSimpleName() + " / cause "
                  + ex.getCause().getMessage()).join();
        System.out.println("handle       : " + h);

        // downstream thenApply is skipped; join wraps the error in CompletionException
        try {
            failing.thenApply(v -> v + 1).join();
        } catch (CompletionException e) {
            System.out.println("join threw   : " + e.getCause());
        }

        // timeouts: neither stops the underlying work
        CompletableFuture<String> slow = new CompletableFuture<>();   // never completes
        System.out.println("completeOnTimeout: "
                + slow.completeOnTimeout("default", 100, TimeUnit.MILLISECONDS).join());
        try {
            new CompletableFuture<String>().orTimeout(100, TimeUnit.MILLISECONDS).join();
        } catch (CompletionException e) {
            System.out.println("orTimeout    : " + e.getCause().getClass().getSimpleName());
        }
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    public static void main(String[] args) throws Exception {
        AtomicInteger done = new AtomicInteger();
        // One cheap virtual thread per task: never pool them
        try (ExecutorService ex = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 10_000; i++) {
                ex.submit(() -> {
                    try {
                        Thread.sleep(200);          // blocking unmounts from the carrier
                    } catch (InterruptedException e) { }
                    done.incrementAndGet();
                });
            }
        } // close() waits for all tasks
        System.out.println("tasks finished = " + done.get());

        Thread vt = Thread.ofVirtual().name("vt-1").start(() -> { });
        vt.join();
        System.out.println("isVirtual = " + vt.isVirtual() + ", daemon = " + vt.isDaemon());
        // 10,000 platform threads sleeping at once would be heavy; virtual ones are not
    }
}

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Semaphore downstream = new Semaphore(5);   // cap calls to a fragile dependency
        AtomicInteger inFlight = new AtomicInteger();
        AtomicInteger maxSeen = new AtomicInteger();

        try (ExecutorService ex = Executors.newVirtualThreadPerTaskExecutor()) {
            for (int i = 0; i < 200; i++) {
                ex.submit(() -> {
                    try {
                        downstream.acquire();          // virtual threads wait cheaply
                        try {
                            int now = inFlight.incrementAndGet();
                            maxSeen.accumulateAndGet(now, Math::max);
                            Thread.sleep(10);          // pretend DB call
                            inFlight.decrementAndGet();
                        } finally {
                            downstream.release();
                        }
                    } catch (InterruptedException e) { }
                    return null;
                });
            }
        }
        System.out.println("200 virtual threads, permits = 5");
        System.out.println("max concurrent calls <= 5: " + (maxSeen.get() <= 5));
    }
}

import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(1);  // only 1 thread

        Future<String> parent = pool.submit(() -> {
            // child goes to the same pool, but the only thread is busy running us
            Future<String> child = pool.submit(() -> "child result");
            return child.get();                 // parent blocks waiting for the child
        });

        try {
            System.out.println(parent.get(500, TimeUnit.MILLISECONDS));
        } catch (TimeoutException e) {
            System.out.println("no progress after 500 ms: thread-starvation deadlock");
        }
        pool.shutdownNow();                      // interrupts the stuck parent

        // Fix: separate pools for parent and child work
        ExecutorService parents = Executors.newFixedThreadPool(1);
        ExecutorService children = Executors.newFixedThreadPool(1);
        Future<String> ok = parents.submit(() -> children.submit(() -> "child result").get());
        System.out.println("with two pools: " + ok.get(2, TimeUnit.SECONDS));
        parents.shutdown();
        children.shutdown();
    }
}
